package android.os; import java.util.HashMap; import java.util.Map; public class Bundle {private final Map<String,Object> values=new HashMap<>(); public CharSequence getCharSequence(String key){return (CharSequence)values.get(key);} public void putCharSequence(String key,CharSequence value){values.put(key,value);} public void putInt(String key,int value){values.put(key,value);} public int getInt(String key){return (Integer)values.getOrDefault(key,0);} }
